diff --git a/src/ui/layout.c b/src/ui/layout.c
new file mode 100644
index 0000000..bb3b5cf
--- /dev/null
+++ b/src/ui/layout.c
@@ -0,0 +1,112 @@
+#include "layout.h"
+#include "stb_ds.h"
+
+// Bounds as the props state them; a Stack's 0 width or height is fitted later.
+static InstanceLayout own_bounds(const ReactInstance *inst)
+{
+    switch (inst->type) {
+    case NT_RECT: {
+        const RectProps *p = &inst->props.rect;
+        return (InstanceLayout){.x = p->x, .y = p->y, .width = p->width, .height = p->height};
+    }
+    case NT_BUTTON: {
+        const ButtonProps *p = &inst->props.button;
+        return (InstanceLayout){.x = p->x, .y = p->y, .width = p->width, .height = p->height};
+    }
+    case NT_TEXT_INPUT: {
+        const TextInputProps *p = &inst->props.text_input;
+        return (InstanceLayout){.x = p->x, .y = p->y, .width = p->width, .height = p->height};
+    }
+    case NT_IMAGE: {
+        const ImageProps *p = &inst->props.image;
+        return (InstanceLayout){.x = p->x, .y = p->y, .width = p->width, .height = p->height};
+    }
+    case NT_STACK:
+    case NT_SCROLL: {
+        const StackProps *p = &inst->props.stack;
+        return (InstanceLayout){.x = p->x, .y = p->y, .width = p->width, .height = p->height};
+    }
+    case NT_TEXT:
+        return (InstanceLayout){.x = inst->props.text.x, .y = inst->props.text.y, .width = inst->props.text.width};
+    case NT_RAW_TEXT:
+        break;
+    }
+    return (InstanceLayout){0};
+}
+
+static bool flows(const ReactInstance *child)
+{
+    switch (child->type) {
+    case NT_RECT:
+    case NT_BUTTON:
+    case NT_TEXT_INPUT:
+    case NT_IMAGE:
+    case NT_STACK:
+        return true;
+    default:
+        return false;
+    }
+}
+
+// Children are already sized and still at their own x/y, so each child's margin and offset are read from its
+// layout before being replaced: the first pass places the main axis, the second the cross axis.
+static void layout_flow(ReactInstance *stack)
+{
+    const StackProps *s = &stack->props.stack;
+    const bool row = s->direction == STACK_ROW;
+    const int count = (int)arrlen(stack->children);
+
+    int flow = 0, cross = 0;
+    bool any = false;
+    for (int i = 0; i < count; i++) {
+        InstanceLayout *c = &stack->children[i]->layout;
+        if (!flows(stack->children[i])) {
+            c->x += s->padding;
+            c->y += s->padding;
+            continue;
+        }
+        int *main_pos = row ? &c->x : &c->y;
+        const int margin = *main_pos;
+        *main_pos = s->padding + flow + margin;
+        flow += margin + (row ? c->width : c->height) + s->gap;
+
+        const int extent = (row ? c->y + c->height : c->x + c->width);
+        if (extent > cross) cross = extent;
+        any = true;
+    }
+
+    const int content_main = (any ? flow - s->gap : 0) + s->padding * 2;
+    const int content_cross = cross + s->padding * 2;
+    InstanceLayout *self = &stack->layout;
+    if (self->width <= 0) self->width = row ? content_main : content_cross;
+    if (self->height <= 0) self->height = row ? content_cross : content_main;
+    self->content_height = row ? content_cross : content_main;
+
+    const int inner_cross = (row ? self->height : self->width) - s->padding * 2;
+    for (int i = 0; i < count; i++) {
+        if (!flows(stack->children[i])) continue;
+        InstanceLayout *c = &stack->children[i]->layout;
+        int *cross_pos = row ? &c->y : &c->x;
+        const int slack = inner_cross - (row ? c->height : c->width);
+        const int aligned = s->align == STACK_ALIGN_CENTER ? slack / 2 : s->align == STACK_ALIGN_END ? slack : 0;
+        *cross_pos = s->padding + aligned + *cross_pos;
+    }
+}
+
+static void layout_instance(ReactInstance *inst)
+{
+    inst->layout = own_bounds(inst);
+    const int count = (int)arrlen(inst->children);
+    for (int i = 0; i < count; i++) {
+        layout_instance(inst->children[i]);
+    }
+    if (inst->type == NT_STACK || inst->type == NT_SCROLL) layout_flow(inst);
+}
+
+void layout_tree(ReactInstance **roots)
+{
+    const int count = (int)arrlen(roots);
+    for (int i = 0; i < count; i++) {
+        layout_instance(roots[i]);
+    }
+}

diff --git a/src/ui/instance_tree.h b/src/ui/instance_tree.h
index 170028d..c507eb9 100644
--- a/src/ui/instance_tree.h
+++ b/src/ui/instance_tree.h
@@ -2,6 +2,7 @@
 #define INSTANCE_TREE_H

 #include <stdbool.h>
+#include <stddef.h>
 #include <raylib.h>

 // Longest instance id including its terminator; native create calls reject longer ids.
@@ -15,6 +16,7 @@ typedef enum {
     NT_SCROLL = 5,
     NT_IMAGE = 6,
     NT_TEXT_INPUT = 7,
+    NT_STACK = 8,
 } NodeType;

 typedef struct {
@@ -67,19 +69,34 @@ typedef struct {
     char *placeholder;
 } TextInputProps;

+typedef enum { STACK_COLUMN = 0, STACK_ROW = 1 } StackDirection;
+
+typedef enum { STACK_ALIGN_START = 0, STACK_ALIGN_CENTER = 1, STACK_ALIGN_END = 2 } StackAlign;
+
+// A Stack, and a Scroll, which is a column Stack that scrolls. A width or height of 0 fits the content.
 typedef struct {
     int x, y, width, height;
     bool has_fill;
     Color fill_color;
+    StackDirection direction;
+    StackAlign align;
     int gap;
     int padding;
-} ScrollProps;
+} StackProps;

 typedef struct {
     char *image_name;
     int x, y, width, height;
 } ImageProps;

+// Bounds relative to the parent's top-left, computed from props by layout_tree on every swap.
+// A Scroll's offset is not part of it: the offset changes without a swap, so readers subtract it.
+typedef struct {
+    int x, y, width, height;
+    // Flowed content height of a Stack or Scroll, including padding; a Scroll's scroll range comes from it.
+    int content_height;
+} InstanceLayout;
+
 typedef struct ReactInstance ReactInstance;

 struct ReactInstance {
@@ -90,23 +107,15 @@ struct ReactInstance {
         TextProps text;
         ButtonProps button;
         TextInputProps text_input;
-        ScrollProps scroll;
+        StackProps stack;
         ImageProps image;
         char *raw_text;
     } props;
+    InstanceLayout layout;
     ReactInstance **children;
     ReactInstance *parent;
 };

-// Minimal column layout for scroll containers. Rect, button, text input and image children
-// participate in the flow: each is placed at the current flow position
-// (its own y acts as a top margin) and advances the flow by margin +
-// height + gap. Returns false for children that are not part of the flow.
-bool scroll_flow_step(const ReactInstance *child, int gap, int *flow_y, int *base_y_out);
-
-// Total stacked content height of a scroll container, including padding.
-int scroll_content_height(const ReactInstance *scroll);
-
 // Look up a scroll container in the front snapshot (thread-safe).
 // Returns false when id is not a scroll container.
 bool instance_scroll_metrics(const char *id, int *viewport_height, int *content_height);
